create table eba_demo_dg_products (
    product_id         number
        generated by default on null as identity
    not null enable,
    product_name       varchar2(255 byte) not null enable,
    unit_price         number(10, 2),
    image_mime_type    varchar2(512 byte),
    image_filename     varchar2(512 byte),
    image_charset      varchar2(512 byte),
    image_last_updated date
);

alter table eba_demo_dg_products
    add constraint eba_demo_dg_prod_pk primary key ( product_id )
        using index enable;


